import subprocess


def convert_document(src_path):
    """文档转换工具：运维平台把用户上传的文件名传入。"""
    banned = [";", "&", "|", "`", "$("]
    for b in banned:
        if b in src_path:
            raise ValueError("illegal filename")
    cmd = "libreoffice --headless --convert-to pdf " + src_path
    return subprocess.run(cmd, shell=True, capture_output=True)
